# 战斗模拟器
import random

def attack(attacker, defender):
    damage = random.randint(5, 15)
    defender["hp"] -= damage
    return damage

player = {"name": "勇者", "hp": 100}
enemy = {"name": "史莱姆", "hp": 50}

damage = attack(player, enemy)
print(f"造成{damage}点伤害！")

