# 简单查找
def find_number(numbers, target):
    for num in numbers:
        if num == target:
            return True
    return False

print(find_number([1,2,3,4,5], 3))

# 异常处理
try:
    num = int(input("输入数字: "))
    result = 10 / num
    print(result)
except ValueError:
    print("请输入数字！")
except ZeroDivisionError:
    print("不能除以零！")

# 类和对象
class Player:
    def __init__(self, name, level):
        self.name = name
        self.level = level

    def greet(self):
        print(f"我是{self.name}，等级{self.level}！")

player = Player("勇者", 10)
player.greet()

# 递归函数
def factorial(n):
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))  # 120
